--
-- Name: v_active_alerts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_active_alerts AS
 SELECT a.alert_id,
    a.created_at,
    a.predicted_for,
    a.source,
    a.severity,
    a.status,
    a.alert_type,
    a.title,
    a.description,
    e.code AS equipment_code,
    z.name AS zone_name,
    a.confidence,
    a.estimated_impact_t,
    a.estimated_impact_tph
   FROM ((public.alerts a
     LEFT JOIN public.equipment e ON ((e.equipment_id = a.equipment_id)))
     LEFT JOIN public.zones z ON ((z.zone_id = a.zone_id)))
  WHERE (a.status <> 'RESOLVED'::public.alert_status)
  ORDER BY
        CASE a.severity
            WHEN 'CRITICAL'::public.alert_severity THEN 1
            WHEN 'WARNING'::public.alert_severity THEN 2
            ELSE 3
        END, a.created_at DESC;


ALTER VIEW public.v_active_alerts OWNER TO postgres;

--
-- Name: v_equipment_live; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_equipment_live AS
 SELECT e.equipment_id,
    e.code,
    e.type,
    e.current_state,
    p.ts AS position_ts,
    public.st_y(p."position") AS latitude,
    public.st_x(p."position") AS longitude,
    p.speed_kmh,
    p.heading_deg,
    p.zone_id,
    t.ts AS telemetry_ts,
    t.fuel_level_pct,
    t.fuel_rate_lph,
    t.engine_rpm,
    t.engine_temp_c,
    t.payload_t,
    t.communication_quality
   FROM ((public.equipment e
     LEFT JOIN LATERAL ( SELECT ep.position_id,
            ep.equipment_id,
            ep.ts,
            ep."position",
            ep.altitude_m,
            ep.speed_kmh,
            ep.heading_deg,
            ep.gps_accuracy_m,
            ep.zone_id,
            ep.telemetry_age_sec,
            ep.metadata
           FROM public.equipment_positions ep
          WHERE (ep.equipment_id = e.equipment_id)
          ORDER BY ep.ts DESC
         LIMIT 1) p ON (true))
     LEFT JOIN LATERAL ( SELECT et.telemetry_id,
            et.equipment_id,
            et.ts,
            et.speed_kmh,
            et.engine_rpm,
            et.engine_load_pct,
            et.fuel_level_pct,
            et.fuel_rate_lph,
            et.engine_temp_c,
            et.coolant_temp_c,
            et.oil_pressure_kpa,
            et.engine_hours,
            et.odometer_km,
            et.payload_t,
            et.battery_voltage,
            et.communication_quality,
            et.raw_data
           FROM public.equipment_telemetry et
          WHERE (et.equipment_id = e.equipment_id)
          ORDER BY et.ts DESC
         LIMIT 1) t ON (true))
  WHERE (e.active = true);


ALTER VIEW public.v_equipment_live OWNER TO postgres;

